     21	// RegisterRoutes registers HTTP file serving routes.
     22	func (s *FileServerService) RegisterRoutes(echoServer *echo.Echo) {
     23		fileGroup := echoServer.Group("/file")
     24		fileGroup.GET("/attachments/:uid/:filename", s.serveAttachmentFile)
     25		fileGroup.GET("/users/:identifier/avatar", s.serveUserAvatar)
