     31	
     32	// serveAttachmentFile serves attachment binary content using native HTTP.
     33	func (s *FileServerService) serveAttachmentFile(c *echo.Context) error {
     34		ctx := c.Request().Context()
     35		uid := c.Param("uid")
     36		wantThumbnail := c.QueryParam("thumbnail") == "true"
